(function(){'use strict';
const $=id=>document.getElementById(id),B=window.DesktopApp?.avalon;let state=null,working=false,painted=false,lastResult='',shortcut='CommandOrControl+Shift+P',region={x:.55,y:.75,width:.45,height:.25};
$('roads-engine-settings').innerHTML=`<details id="roads-native-settings"><summary>Настройки сканера</summary><div class="roads-controls"><label class="field">Кнопка сканирования<select id="engine-trigger"><option value="keyboard">Клавиатура</option><option value="middle">Средняя кнопка мыши</option><option value="mouse4">Боковая кнопка мыши 1</option><option value="mouse5">Боковая кнопка мыши 2</option></select></label><label class="field">Клавиша или сочетание<input id="engine-shortcut" readonly aria-label="Нажмите сюда и задайте клавишу сканирования"></label><label class="field">Точность названия, %<input id="engine-score" type="number" min="60" max="100" value="78"></label><label class="field">Закрывать карту через, сек (0 — вручную)<input id="engine-close-time" type="number" min="0" max="60" value="0"></label></div><p class="hint">Чтобы назначить клавишу, нажмите на поле и затем нужную клавишу или сочетание. Для смены кнопки выключите сканер.</p><div class="avalon-actions"><label><input id="engine-auto-from" type="checkbox" checked> Читать текущую зону с экрана</label><label><input id="engine-map" type="checkbox" checked> Открывать карту поверх игры</label></div><label class="field">Текущая зона при ручном выборе<input id="engine-current" list="avalon-zone-list" maxlength="100" disabled placeholder="Выберите точное название зоны"></label><p id="engine-region" class="hint"></p><div class="avalon-actions"><button id="engine-calibrate" class="button">Указать область названия зоны</button><button id="engine-settings-save" class="button">Сохранить настройки</button></div><p class="hint">Для области считывания покажите в игре название текущей зоны. Снимок появится через 3 секунды; обведите только название. При ручном выборе обновляйте текущую зону после перехода.</p></details>`;
function message(text,bad=false){$('roads-status').textContent=text;$('roads-status').classList.toggle('avalon-error',bad);}
const shortcutLabel=value=>value.replace('CommandOrControl','Ctrl').replace(/\bControl\b/g,'Ctrl').replace(/\bSuper\b/g,'Win');
function fields(s){region={...s.region};shortcut=s.shortcut||'CommandOrControl+Shift+P';$('engine-shortcut').value=shortcutLabel(shortcut);$('engine-trigger').value=s.trigger;$('engine-score').value=s.minScore;$('engine-close-time').value=s.overlaySeconds;$('engine-auto-from').checked=s.autoFrom;$('engine-map').checked=s.showMap;$('engine-current').value=AvalonUI.catalog().find(z=>z.id===s.currentId)?.name||'';}
function values(){const current=AvalonUI.catalog().find(z=>AvalonMath.normalize(z.name)===AvalonMath.normalize($('engine-current').value));if(!$('engine-auto-from').checked&&!current)throw Error('Выберите точное название текущей зоны из подсказок.');return {trigger:$('engine-trigger').value,shortcut,minScore:Number($('engine-score').value),overlaySeconds:Number($('engine-close-time').value),autoFrom:$('engine-auto-from').checked,showMap:$('engine-map').checked,currentId:current?.id||'',region};}
function controls(){const session=state?.session;for(const id of ['roads-engine-import','roads-engine-choose'])$(id).disabled=working||!!session;$('roads-record').textContent=session?'Выключить сканер':'Включить сканер';$('roads-record').disabled=working||(!session&&(!B||!state?.available));$('engine-trigger').disabled=working||!!session;$('engine-shortcut').disabled=working||!!session||$('engine-trigger').value!=='keyboard';$('engine-current').disabled=$('engine-auto-from').checked;$('engine-calibrate').disabled=working;$('engine-settings-save').disabled=working;$('engine-region').textContent=region.width>.4||region.height>.2?'Область текущей зоны слишком большая: обведите только название на мини-карте, иначе можно прочитать другую зону.':`Область текущей зоны: ${Math.round(region.width*100)}% × ${Math.round(region.height*100)}% экрана.`;
 $('roads-engine').textContent=!B?'Сканер доступен в настольном приложении.':state?.available?`Движок подключён. ${session?'Сканер включён. Наведите курсор на подсказку и нажмите '+(session.trigger==='keyboard'?shortcutLabel(session.shortcut):({middle:'среднюю кнопку мыши',mouse4:'боковую кнопку 1',mouse5:'боковую кнопку 2'}[session.trigger]))+'.':'Сканер выключен. После включения считывание выполняется только по назначенной кнопке.'}`:'Сначала подключите движок Checker.';
}
async function refresh(){if(!B||working)return;try{state=await B.engine('status');if(!painted&&AvalonUI.catalog().length){fields(state.settings);painted=true;}const signature=JSON.stringify([state.error,state.lastScan]);if(signature!==lastResult){lastResult=signature;if(state.error)message(state.error,true);else if(state.lastScan){const r=state.lastScan;message(`${r.from||'?'} → ${r.to||'?'} · ${r.seconds===null?'таймер не прочитан':r.timerText||Math.floor(r.seconds/3600)+' ч '+Math.floor(r.seconds%3600/60)+' мин '+r.seconds%60+' с'}${r.recorded?' · сохранено':''}`);}}controls();window.AvalonRoadsUI?.render();}catch(e){message(e.message,true);}}
async function run(fn,text){if(working)return false;working=true;controls();if(text)message(text);try{await fn();return true;}catch(e){message(e.message,true);return false;}finally{working=false;await refresh();}}
$('roads-engine-import').onclick=()=>run(async()=>{state=await B.engine('import');painted=false;await AvalonUI.load(true);},'Подключаю библиотеки распознавания к Albion Lab…');$('roads-engine-choose').onclick=()=>run(async()=>{state=await B.engine('choose');painted=false;await AvalonUI.load(true);},'Выберите AlbionAvalonChecker.exe из полной скачанной папки…');
$('engine-shortcut').onkeydown=e=>{e.preventDefault();e.stopPropagation();const specials={Space:'Space',Tab:'Tab',Escape:'Escape',Insert:'Insert',Delete:'Delete',Backspace:'Backspace',Enter:'Return',CapsLock:'Capslock',NumLock:'Numlock',ScrollLock:'Scrolllock',PrintScreen:'PrintScreen',Home:'Home',End:'End',PageUp:'PageUp',PageDown:'PageDown',ArrowUp:'Up',ArrowDown:'Down',ArrowLeft:'Left',ArrowRight:'Right',NumpadDecimal:'numdec',NumpadAdd:'numadd',NumpadSubtract:'numsub',NumpadMultiply:'nummult',NumpadDivide:'numdiv',Minus:'-',Equal:'=',Comma:',',Period:'.',Slash:'/',Semicolon:';',Backquote:'`',BracketLeft:'[',BracketRight:']',Backslash:'\\'};const key=/^Key[A-Z]$/.test(e.code)?e.code.slice(3):/^Digit[0-9]$/.test(e.code)?e.code.slice(5):/^Numpad[0-9]$/.test(e.code)?'num'+e.code.slice(6):/^F(?:[1-9]|1\d|2[0-4])$/.test(e.code)?e.code:specials[e.code];if(!key)return;shortcut=[...(e.ctrlKey?['CommandOrControl']:[]),...(e.altKey?['Alt']:[]),...(e.shiftKey?['Shift']:[]),...(e.metaKey?['Super']:[]),key].join('+');$('engine-shortcut').value=shortcutLabel(shortcut);};
$('engine-settings-save').onclick=()=>run(async()=>{state=await B.engine('settings',values());message('Настройки сканера сохранены.');});$('engine-auto-from').onchange=controls;$('engine-trigger').onchange=controls;
$('roads-record').onclick=()=>run(async()=>{if(state?.session){state=await B.engine('stop');message('Сканер выключен. Граф сохранён.');}else{state=await B.engine('settings',values());state=await B.engine('start',{server:ActivityViews.avalon.state.server});message('Сканер включён. Наведите курсор на подсказку портала и нажмите назначенную кнопку.');}},state?.session?'Выключаю сканер…':'Запускаю сканер…');
const calibration=document.createElement('dialog');calibration.className='engine-calibration';calibration.innerHTML='<h2>Обведите название текущей зоны</h2><p class="hint">Только название зоны на мини-карте, без названия назначения портала.</p><div class="engine-crop"><img alt="Снимок для выбора области" draggable="false"><div class="engine-crop-rect"></div></div><div class="avalon-actions"><button class="button" id="engine-crop-save" disabled>Использовать область</button><button class="button" id="engine-crop-cancel">Отмена</button></div>';document.body.append(calibration);const img=calibration.querySelector('img'),rect=calibration.querySelector('.engine-crop-rect');let anchor=null,selection=null;
function point(e){const r=img.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))};}
img.onpointerdown=e=>{anchor=point(e);img.setPointerCapture(e.pointerId);selection=null;$('engine-crop-save').disabled=true;e.preventDefault();};img.onpointermove=e=>{if(!anchor)return;const p=point(e);selection={x:Math.min(anchor.x,p.x),y:Math.min(anchor.y,p.y),width:Math.abs(p.x-anchor.x),height:Math.abs(p.y-anchor.y)};rect.style.cssText=`display:block;left:${selection.x*100}%;top:${selection.y*100}%;width:${selection.width*100}%;height:${selection.height*100}%`;$('engine-crop-save').disabled=selection.width<.01||selection.height<.01;};img.onpointerup=()=>anchor=null;
$('engine-calibrate').onclick=()=>run(async()=>{if(state?.session)state=await B.engine('stop');await new Promise(r=>setTimeout(r,3000));const result=await B.engine('calibrate');selection=null;rect.style.display='none';img.src=result.image;calibration.showModal();},'Через 3 секунды появится снимок. Переключитесь в игру и покажите название текущей зоны…');$('engine-crop-cancel').onclick=()=>calibration.close();$('engine-crop-save').onclick=async()=>{if(!selection)return;const old=region;region=selection;if(await run(async()=>{state=await B.engine('settings',values());message('Область сохранена. Можно начать запись переходов.');}))calibration.close();else region=old;};calibration.addEventListener('close',()=>{img.removeAttribute('src');selection=null;anchor=null;});
document.addEventListener('workspacechange',event=>{if(event.detail?.navigation){painted=false;refresh();}});B?.onRoads(refresh);setInterval(()=>{if(ActivityViews.avalon.active())refresh();},2000);window.AvalonEngineUI={refresh,snapshot:()=>({...state,busy:working})};controls();
})();
